<?php requireLogin(); ?><section class="hero"><h1>💬 Messaging</h1><p>Direct communication between students and tutors can use this module.</p></section><div class="card"><p>Enter the other user's ID for the prototype messaging test.</p><input id="to" placeholder="User ID"><textarea id="body" placeholder="Write your message..."></textarea><button class="btn" onclick="send()">Send</button><div id="chat"></div></div><script>async function send(){let f=new FormData();f.append('action','send');f.append('to_user_id',document.getElementById('to').value);f.append('body',document.getElementById('body').value);f.append('csrf',window.CSRF);await post('backend/api/messages.php',f);document.getElementById('body').value='';load()}async function load(){let id=document.getElementById('to').value;if(!id)return;let a=await api('backend/api/messages.php?with='+id);document.getElementById('chat').innerHTML=a.map(x=>`<p><strong>${escapeHTML(x.sender_name)}:</strong> ${escapeHTML(x.body)}</p>`).join('')}setInterval(load,3000)</script>
